package com.estoqueinteligente.product;
import java.math.BigDecimal;import java.time.LocalDate;import jakarta.validation.constraints.*;
public class ProductRequest{@NotBlank(message="O nome é obrigatório")@Size(max=150)private String name;@Size(max=50)private String barcode;@NotNull(message="A categoria é obrigatória")private Long categoryId;private Long supplierId;@NotNull(message="O preço de custo é obrigatório")@DecimalMin(value="0.0",message="O preço de custo não pode ser negativo")private BigDecimal costPrice;@NotNull(message="O preço de venda é obrigatório")@DecimalMin(value="0.0",message="O preço de venda não pode ser negativo")private BigDecimal salePrice;@NotNull(message="A quantidade é obrigatória")@Min(value=0,message="A quantidade não pode ser negativa")private Integer quantity;@NotNull(message="O estoque mínimo é obrigatório")@Min(value=0,message="O estoque mínimo não pode ser negativo")private Integer minimumStock;private LocalDate expirationDate;public ProductRequest(){}public String name(){return name;}public String getName(){return name;}public void setName(String v){name=v;}public String barcode(){return barcode;}public String getBarcode(){return barcode;}public void setBarcode(String v){barcode=v;}public Long categoryId(){return categoryId;}public Long getCategoryId(){return categoryId;}public void setCategoryId(Long v){categoryId=v;}public Long supplierId(){return supplierId;}public Long getSupplierId(){return supplierId;}public void setSupplierId(Long v){supplierId=v;}public BigDecimal costPrice(){return costPrice;}public BigDecimal getCostPrice(){return costPrice;}public void setCostPrice(BigDecimal v){costPrice=v;}public BigDecimal salePrice(){return salePrice;}public BigDecimal getSalePrice(){return salePrice;}public void setSalePrice(BigDecimal v){salePrice=v;}public Integer quantity(){return quantity;}public Integer getQuantity(){return quantity;}public void setQuantity(Integer v){quantity=v;}public Integer minimumStock(){return minimumStock;}public Integer getMinimumStock(){return minimumStock;}public void setMinimumStock(Integer v){minimumStock=v;}public LocalDate expirationDate(){return expirationDate;}public LocalDate getExpirationDate(){return expirationDate;}public void setExpirationDate(LocalDate v){expirationDate=v;}}
